INSERT INTO `destinations` VALUES (1,'Paris','France','Europe','International',6,'Paris, France capital, is a major European city and a global center for art, fashion, gastronomy and culture. Its 19th-century cityscape is crisscrossed by wide boulevards and the River Seine. Beyond such landmarks as the Eiffel Tower and the 12th-century, Gothic Notre-Dame cathedral, the city is known for its cafe culture and designer boutiques.','April to October','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=800&q=80',4.80,'Luxury',48.85661400,2.35222190,'Eiffel Tower & Champ de Mars, Louvre Museum & Glass Pyramid, Arc de Triomphe & Champs-Élysées'),(2,'Manali','India','Asia','National',1,'Manali is a high-altitude Himalayan resort town in IndiaÔÇÖs northern Himachal Pradesh state. It has a reputation as a backpacking center and honeymoon destination. Set on the Beas River, itÔÇÖs a gateway for skiing in the Solang Valley and trekking in Parvati Valley. ItÔÇÖs also a jumping-off point for paragliding, rafting and mountaineering in the Pir Panjal mountains.','October to June','https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?auto=format&fit=crop&w=800&q=80',4.50,'Budget',32.23963250,77.18871450,'Solang Valley Snow Point, Hadimba Temple & Dhungri Van Vihar, Rohtang Pass & Atal Tunnel'),(3,'Bali','Indonesia','Asia','International',2,'Bali is a province of Indonesia and the westernmost of the Lesser Sunda Islands. East of Java and west of Lombok, the province includes the island of Bali and a few smaller neighbouring islands. Bali is Indonesia\'s main tourist destination, with a significant rise in tourism since the 1980s. Tourism-related business makes up 80% of its economy.','April to October','https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=80',4.70,'Mid-Range',-8.40951800,115.18891600,'Ubud Sacred Monkey Forest Sanctuary, Uluwatu Cliff Temple & Kecak Dance, Tegallalang Rice Terraces'),(4,'Machu Picchu','Peru','South America','International',3,'Machu Picchu is an Incan citadel set high in the Andes Mountains in Peru, above the Urubamba River valley. Built in the 15th century and later abandoned, itÔÇÖs renowned for its sophisticated dry-stone walls that fuse huge blocks without the use of mortar, intriguing buildings that play on astronomical alignments and panoramic views.','May to September','https://images.unsplash.com/photo-1509024644558-2f56ce76c490?auto=format&fit=crop&w=800&q=80',4.90,'Luxury',-13.16314120,-72.54496290,'Huayna Picchu Mountain Peak, Intihuatana Ritual Sun Stone, Sun Gate (Inti Punku)'),(5,'Serengeti National Park','Tanzania','Africa','International',4,'The Serengeti National Park is a Tanzanian national park in the Serengeti ecosystem in the Mara and Simiyu regions. It is famous and well-known for its annual migration of over 1.5 million white-bearded wildebeest and 250,000 zebra and for its numerous Nile crocodile and honey badger.','July to October','https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=800&q=80',4.80,'Luxury',-2.15400700,34.68565900,'Grumeti & Mara River Crossing, Seronera Valley Wildlife Loop, Retima Hippo Pool'),(6,'Queenstown','New Zealand','Oceania','International',5,'Queenstown, New Zealand, is situated on the shores of the South IslandÔÇÖs Lake Wakatipu, set against the dramatic Southern Alps. Renowned for adventure sports, itÔÇÖs also a base for exploring the regionÔÇÖs vineyards and historic mining towns. ThereÔÇÖs bungee jumping from Kawarau Bridge and jet-boating on the Shotover and Dart rivers.','December to February','https://images.unsplash.com/photo-1507699622108-4be3abd695ad?auto=format&fit=crop&w=800&q=80',4.90,'Luxury',-45.03116220,168.66264350,'Milford Sound Fjord Cruise, Skyline Gondola & Bob’s Peak Luge, Kawarau Bridge Bungee Jump'),(7,'Tokyo','Japan','Asia','International',6,'Tokyo, JapanÔÇÖs bustling capital, mixes ultra-modern and traditional skyscrapers with neon-lit signs and historic temples. The opulent Meiji Shinto Shrine is known for its towering gate and surrounding woods. The Imperial Palace sits amid large public gardens. The city is also famous for its world-class food scene.','March to May & September to November','https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=80',4.70,'Mid-Range',35.67619190,139.65031060,'Sensō-ji Temple & Nakamise Street, Shibuya Scramble Crossing, Tokyo Skytree Tower'),(8,'Maldives','Maldives','Asia','International',2,'The Maldives is a nation of islands in the Indian Ocean, that spans across the equator. The country is comprised of 1192 islands that stretch along a length of 871 kilometers. The Maldives is famous for its crystal clear blue waters, white sand beaches, and luxurious overwater bungalows.','November to April','https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=800&q=80',4.90,'Luxury',3.20277800,73.22068000,'Banana Reef Marine Reserve, Vaadhoo Sea of Stars Beach, Malé Grand Friday Mosque'),(9,'Grand Canyon','USA','North America','International',5,'The Grand Canyon in Arizona is a natural formation distinguished by layered bands of red rock, revealing millions of years of geological history. Much of the area is national park, with Colorado River white-water rapids and sweeping vistas. Popular viewpoints include Mather Point, Yavapai Observation Station and Lipan Point.','March to May & September to November','https://images.unsplash.com/photo-1615551043360-33de8b5f410c?auto=format&fit=crop&w=800&q=80',4.80,'Mid-Range',36.05444450,-112.14011080,'South Rim Mather Point, Bright Angel Trail, Desert View Watchtower'),(10,'Rome','Italy','Europe','International',3,'Rome, ItalyÔÇÖs capital, is a sprawling, cosmopolitan city with nearly 3,000 years of globally influential art, architecture and culture on display. Ancient ruins such as the Forum and the Colosseum recall the power of the former Roman Empire. Vatican City, headquarters of the Roman Catholic Church, has St. PeterÔÇÖs Basilica.','April to June & September to October','https://images.unsplash.com/photo-1552832230-c0197dd311b5?auto=format&fit=crop&w=800&q=80',4.70,'Mid-Range',41.90278350,12.49636550,'Colosseum & Roman Forum, Trevi Fountain & Spanish Steps, Vatican Museums & Sistine Chapel'),(11,'Swiss Alps','Switzerland','Europe','International',1,'The Alps are the highest and most extensive mountain range system that lies entirely in Europe, stretching approximately 1,200 km across eight Alpine countries. The Swiss Alps comprise almost all the highest mountains of the Alps, such as the Matterhorn and Jungfrau, and are famous for breathtaking scenery, ski resorts, and hiking trails.','December to March & June to September','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',4.90,'Luxury',46.53673500,7.98181600,'Jungfraujoch Top of Europe, Matterhorn Peak Zermatt, Lake Geneva Promenade'),(13,'Santorini','Greece','Europe','International',2,'Santorini is one of the Cyclades islands in the Aegean Sea. It was devastated by a volcanic eruption in the 16th century BC, forever shaping its rugged landscape. The whitewashed, cubiform houses of its 2 principal towns, Fira and Oia, cling to cliffs above an underwater caldera (crater). They overlook the sea, small islands to the west and beaches made up of black, red and white lava pebbles.','April to October','https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=800&q=80',4.80,'Luxury',36.39315600,25.46150900,'Oia Castle Sunset Point, Red Beach Akrotiri, Caldera Volcanic Boat Tour'),(14,'Angkor Wat','Cambodia','Asia','International',3,'Angkor Wat is a temple complex in Cambodia and the largest religious monument in the world by land area, on a site measuring 162.6 hectares. Originally constructed as a Hindu temple of god Vishnu for the Khmer Empire, it was gradually transformed into a Buddhist temple towards the end of the 12th century.','November to February','https://images.unsplash.com/photo-1543872084-c7bd3822856f?auto=format&fit=crop&w=800&q=80',4.80,'Budget',13.41246930,103.86698070,'Bayon Temple Stone Faces, Ta Prohm (Tomb Raider Temple), Phnom Bakheng Sunset Hill'),(15,'Banff National Park','Canada','North America','International',1,'Banff National Park is Canada\'s oldest national park, established in 1885. Located in the Rocky Mountains, 110ÔÇô180 kilometres west of Calgary in the province of Alberta, Banff encompasses 6,641 square kilometres of mountainous terrain, with many glaciers and ice fields, dense coniferous forest, and alpine landscapes.','June to August & December to March','https://images.unsplash.com/photo-1503614472-8c93d56e92ce?auto=format&fit=crop&w=800&q=80',4.70,'Mid-Range',51.49684600,-115.92805500,'Lake Louise & Victoria Glacier, Moraine Lake & Valley of Ten Peaks, Johnston Canyon Upper Waterfalls'),(16,'Shimla','India','Asia','National',1,'Shimla is the capital of Himachal Pradesh, famous for its colonial architecture, Mall Road, snow-capped mountains, and historic Kalka-Shimla toy train ride.','March to June & Dec to Feb','https://images.unsplash.com/photo-1597074866923-dc0589150358?auto=format&fit=crop&w=800&q=80',4.60,'Budget',31.10480000,77.17340000,'The Ridge, Mall Road, Jakhoo Temple, Kufri'),(17,'Munnar','India','Asia','National',1,'Munnar is a scenic hill station in Kerala famous for its endless tea plantations, misty hills, exotic wildlife in Eravikulam National Park, and pleasant climate.','September to March','https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=800&q=80',4.75,'Mid-Range',10.08890000,77.05950000,'Eravikulam National Park, Mattupetty Dam & Lake, Tea Museum & Lockhart Plantation'),(18,'Ooty','India','Asia','National',1,'Known as the Queen of Hill Stations in Tamil Nadu, Ooty features lush Nilgiri mountains, botanical gardens, serene lakes, and colonial charm.','October to June','https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?auto=format&fit=crop&w=800&q=80',4.50,'Budget',11.41020000,76.69500000,'Ooty Lake & Boathouse, Doddabetta Peak Viewpoint, Government Botanical Gardens'),(19,'Darjeeling','India','Asia','National',1,'Darjeeling is renowned worldwide for its aromatic black tea, views of Mount Kanchenjunga, and the UNESCO Heritage Himalayan Railway toy train.','April to June & Oct to Dec','https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=800&q=80',4.65,'Mid-Range',27.04100000,88.26630000,'Tiger Hill Sunrise Viewpoint, Batasia Loop & War Memorial, Japanese Peace Pagoda'),(20,'Goa','India','Asia','National',2,'Goa is India???s beach paradise featuring golden sands, lively nightlife, Portuguese heritage churches, water sports, and delicious seafood.','November to February','https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=800&q=80',4.85,'Mid-Range',15.29930000,74.12400000,'Baga Beach & Tito’s Lane, Aguada Fort & Sinquerim Lighthouse, Dudhsagar Waterfalls'),(21,'Varkala','India','Asia','National',2,'Varkala in Kerala is a coastal town known for its unique red sandstone cliffs overlooking the Arabian Sea, mineral springs, and peaceful beaches.','October to March','https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=800&q=80',4.60,'Budget',8.73790000,76.71630000,'Varkala Cliff, Papanasam Beach, Janardhanaswamy Temple, Kappil Lake'),(22,'Gokarna','India','Asia','National',2,'Gokarna in Karnataka is a pristine coastal town famous for its crescent beaches, laid-back vibe, and sacred Mahabaleshwar Temple.','October to March','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80',4.55,'Budget',14.54790000,74.31880000,'Om Beach & Water Sports, Kudle Beach Cove, Mahabaleshwar Temple'),(23,'Jaipur','India','Asia','National',3,'Jaipur, the Pink City of Rajasthan, boasts magnificent royal palaces, hilltop forts, vibrant bazaars, and rich Rajputana heritage.','October to March','https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80',4.80,'Mid-Range',26.91240000,75.78730000,'Amber Fort & Sheesh Mahal, Hawa Mahal (Palace of Winds), Jal Mahal Water Palace'),(24,'Agra','India','Asia','National',3,'Agra is home to the iconic Taj Mahal, one of the Seven Wonders of the World, along with Agra Fort and Fatehpur Sikri.','October to March','https://images.unsplash.com/photo-1564507592333-c60657eea523?auto=format&fit=crop&w=800&q=80',4.90,'Luxury',27.17670000,78.00810000,'Taj Mahal Monument of Love, Agra Fort Red Sandstone Citadel, Mehtab Bagh Sunset View Point'),(25,'Varanasi','India','Asia','National',3,'Varanasi is one of the world???s oldest continuously inhabited cities, sacred to Hindus with ancient riverbank Ghats and spiritual evening Aarti.','October to March','https://images.unsplash.com/photo-1561361513-2d000a50f0dc?auto=format&fit=crop&w=800&q=80',4.70,'Budget',25.31760000,82.97390000,'Dashashwamedh Ghat & Evening Aarti, Kashi Vishwanath Temple, Sarnath Buddhist Stupa Site'),(26,'Amritsar','India','Asia','National',3,'Amritsar in Punjab is the spiritual center of Sikhism, world-famous for the Golden Temple, Wagah Border ceremony, and delicious Punjabi cuisine.','October to March','https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=800&q=80',4.85,'Budget',31.63400000,74.87230000,'Golden Temple (Harmandir Sahib), Wagah Border Beating Retreat Ceremony, Jallianwala Bagh Memorial Garden'),(27,'Udaipur','India','Asia','National',3,'Known as the City of Lakes, Udaipur in Rajasthan features romantic marble palaces on Lake Pichola, royal gardens, and royal heritage.','October to March','https://images.unsplash.com/photo-1615836245337-f5b9b2303f10?auto=format&fit=crop&w=800&q=80',4.85,'Luxury',24.58540000,73.71250000,'City Palace Udaipur, Lake Pichola Boat Ride & Jagmandir, Saheliyon-ki-Bari Royal Gardens'),(28,'Mysore','India','Asia','National',3,'Mysore in Karnataka is famed for its grand Mysore Palace, silk saris, sandalwood crafts, and rich cultural royal heritage.','October to March','https://images.unsplash.com/photo-1582510003544-4d00b7f74220?auto=format&fit=crop&w=800&q=80',4.60,'Mid-Range',12.29580000,76.63940000,'Mysore Palace (Amba Vilas), Chamundi Hill & Chamundeshwari Temple, Brindavan Gardens & Musical Fountains'),(29,'Ranthambore','India','Asia','National',4,'Ranthambore National Park in Rajasthan is one of India???s premier tiger reserves, featuring wild Bengal tigers roaming amid ancient fort ruins.','October to June','https://images.unsplash.com/photo-1575550959106-5a7defe28b56?auto=format&fit=crop&w=800&q=80',4.75,'Luxury',26.01730000,76.50260000,'Ranthambore Fort Ruins, Padam Talao & Jogi Mahal, Trinetra Ganesha Temple'),(30,'Jim Corbett','India','Asia','National',4,'India???s oldest national park located in Uttarakhand, famous for Royal Bengal tigers, wild elephants, river rafting, and forest safaris.','November to June','https://images.unsplash.com/photo-1549366021-9f761d450615?auto=format&fit=crop&w=800&q=80',4.65,'Mid-Range',29.53000000,78.77470000,'Dhikala Tiger Zone Safari, Garjiya Devi River Temple, Corbett Waterfall'),(31,'Kaziranga','India','Asia','National',4,'A UNESCO World Heritage Site in Assam, Kaziranga is home to two-thirds of the world???s great one-horned rhinoceroses and dense elephant grass marshes.','November to April','https://images.unsplash.com/photo-1534567153574-2b12153a87f0?auto=format&fit=crop&w=800&q=80',4.80,'Mid-Range',26.57750000,93.17110000,'Central Range Elephant Safari, Kaziranga National Orchid & Biodiversity Park, Kakochang Waterfalls'),(32,'Rishikesh','India','Asia','National',5,'Rishikesh in Uttarakhand is the Yoga Capital of the World, nestled along the holy Ganges River, offering white-water rafting, bungee jumping, and spiritual ashrams.','September to June','https://images.unsplash.com/photo-1590766940554-634a7ed41450?auto=format&fit=crop&w=800&q=80',4.75,'Budget',30.08690000,78.26760000,'Laxman Jhula & Ram Jhula Suspended Bridges, Triveni Ghat Evening Ganga Aarti, Beatles Ashram (Chaurasi Kutia)'),(33,'Leh Ladakh','India','Asia','National',5,'Ladakh is a high-altitude cold desert offering surreal landscapes, crystal-clear Pangong Lake, high mountain passes, and Buddhist monasteries.','May to September','https://images.unsplash.com/photo-1581793745862-99fde7fa73d2?auto=format&fit=crop&w=800&q=80',4.90,'Luxury',34.15260000,77.57710000,'Pangong Tso High Altitude Lake, Nubra Valley & Hunder Sand Dunes, Khardung La Pass'),(34,'Spiti Valley','India','Asia','National',5,'Spiti Valley is a remote Himalayan cold desert valley in Himachal Pradesh, famous for ancient monasteries, rugged roads, and starlit night skies.','June to September','https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?auto=format&fit=crop&w=800&q=80',4.80,'Mid-Range',32.24610000,78.03490000,'Key Monastery (Ki Gompa), Chandratal Moon Lake, Hikkim Highest Post Office'),(35,'Mumbai','India','Asia','National',6,'Mumbai, India???s financial capital and home of Bollywood, features colonial architecture, Marine Drive skyline, bustling markets, and street food.','October to March','https://images.unsplash.com/photo-1570168007204-dfb528c6958f?auto=format&fit=crop&w=800&q=80',4.65,'Luxury',18.92200000,72.83470000,'Gateway of India & Taj Mahal Palace, Marine Drive Queens Necklace, Elephanta Island Cave Temples'),(36,'New Delhi','India','Asia','National',6,'India???s bustling capital city blending historic monuments like Qutub Minar and Red Fort with modern shopping, government avenues, and rich food markets.','October to March','https://images.unsplash.com/photo-1587474260584-136574528ed5?auto=format&fit=crop&w=800&q=80',4.60,'Mid-Range',28.61390000,77.20900000,'Qutub Minar Complex, India Gate & Kartavya Path, Humayun’s Tomb Garden Mausoleum'),(38,'Kyoto','Japan','Asia','International',3,'Kyoto, once the capital of Japan, is a city on the island of Honshu. It is famous for its numerous classical Buddhist temples, gardens, imperial palaces, Shinto shrines and traditional wooden houses.','March to May & Oct to Nov','https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=80',4.90,'Luxury',35.01160000,135.76810000,'Fushimi Inari Taisha, Arashiyama Bamboo Grove, Kinkaku-ji (Golden Pavilion), Gion District'),(39,'Dubai','UAE','Asia','International',6,'Dubai is a city and emirate in the United Arab Emirates known for luxury shopping, ultramodern architecture and a lively nightlife scene. Burj Khalifa, an 830m-tall tower, dominates the skyscraper-filled skyline.','November to April','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=800&q=80',4.85,'Luxury',25.20480000,55.27080000,'Burj Khalifa, Dubai Mall, Palm Jumeirah, Desert Safari, Miracle Garden'),(41,'Coorg','India','Asia','National',1,'Coorg (Kodagu), known as the Scotland of India, is an enchanting hill station in Karnataka renowned for lush coffee plantations, misty valleys, cascades, and rich Kodava culture.','October to March','https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=800&q=80',4.70,'Mid-Range',12.42440000,75.73820000,'Abbey Falls, Raja’s Seat, Namdroling Monastery (Golden Temple), Dubare Elephant Camp');
