/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` VALUES (1,'How do I book a tour package, hotel, or guide on TravelPortal?','Simply browse to your desired Package, Hotel, or Guide page, select your preferred dates and guest count, click \"Book Now\", apply any discount offer codes on the checkout page, and confirm your booking instantly.',1,'2026-07-20 00:30:58'),(2,'Are all tour guides verified on TravelPortal?','Yes! All local tour guides listed on TravelPortal undergo background checks, identity verification, and license verification before being registered.',2,'2026-07-20 00:30:58'),(3,'What is the refund and cancellation policy?','You can cancel any pending or confirmed booking directly from your user profile under \"My Bookings\". Cancellations made at least 48 hours prior to check-in/start date receive a 100% full refund.',3,'2026-07-20 00:30:58'),(4,'How do I apply a promo code for discounts?','During the checkout process on `checkout.php`, enter your promo code in the \"Offer / Coupon Code\" field and click \"Apply\". The total bill will automatically update with your discount.',4,'2026-07-20 00:30:58'),(5,'Do I get instant confirmation for my hotel and package bookings?','Yes. Upon completing checkout, your booking is placed in \"Confirmed\" or \"Pending\" status and an immediate in-app notification + receipt is generated in your user profile.',5,'2026-07-20 00:30:58');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

