DROP TABLE IF EXISTS `guides`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `guides` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `destination_id` int(11) NOT NULL,
  `photo` varchar(255) DEFAULT 'default_destination.jpg',
  `languages` varchar(150) NOT NULL,
  `experience_years` int(11) NOT NULL DEFAULT 1,
  `contact_number` varchar(50) NOT NULL,
  `email` varchar(100) NOT NULL,
  `rating` decimal(3,2) DEFAULT 4.80,
  `price_per_day` decimal(10,2) DEFAULT 1500.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `destination_id` (`destination_id`),
  CONSTRAINT `guides_ibfk_1` FOREIGN KEY (`destination_id`) REFERENCES `destinations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

