INSERT INTO `nearby_places` VALUES (1,2,'Solang Valley','Famous for snow sports including skiing, paragliding, snowmobiling, and ropeway rides.','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=800&q=80&attraction_id=1',13.50,'2026-07-20 00:30:58'),(2,2,'Rohtang Pass','High mountain pass connecting Kullu Valley with Lahaul and Spiti Valleys, known for year-round snow.','https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=800&q=80&attraction_id=2',51.00,'2026-07-20 00:30:58'),(3,20,'Aguada Fort & Lighthouse','17th-century Portuguese fort standing on Sinquerim Beach offering sweeping views of the Arabian Sea.','https://images.unsplash.com/photo-1565099824688-e93eb20fe622?auto=format&fit=crop&w=800&q=80&attraction_id=3',8.20,'2026-07-20 00:30:58'),(4,20,'Dudhsagar Waterfalls','Four-tiered spectacular waterfall located on the Mandovi River amidst lush Bhagwan Mahaveer Sanctuary.','https://images.unsplash.com/photo-1509439581779-6298f75bf6e5?auto=format&fit=crop&w=800&q=80&attraction_id=4',60.00,'2026-07-20 00:30:58'),(5,23,'Amber Fort & Palace','Majestic hilltop fort built from pink and yellow sandstone featuring the stunning Sheesh Mahal (Mirror Palace).','https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?auto=format&fit=crop&w=800&q=80&attraction_id=5',11.00,'2026-07-20 00:30:58'),(6,16,'Kufri','Charming hill station famous for ski slopes, Himalayan Wildlife Park, and pony rides.','https://images.unsplash.com/photo-1605649487212-47bdab064df7?auto=format&fit=crop&w=800&q=80&attraction_id=6',15.00,'2026-07-20 01:30:18'),(7,16,'Chail','Quiet hill retreat housing the highest cricket ground in the world and Chail Palace.','https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=80&attraction_id=7',44.00,'2026-07-20 01:30:18'),(8,17,'Anamudi Peak','The highest peak in South India located inside Eravikulam National Park.','https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=800&q=80&attraction_id=8',13.00,'2026-07-20 01:30:18'),(9,17,'Mattupetty Dam & Lake','Picturesque dam surrounded by tea plantations, ideal for boating and elephant sightings.','https://images.unsplash.com/photo-1512100356356-de1b84283e18?auto=format&fit=crop&w=800&q=80&attraction_id=9',13.00,'2026-07-20 01:30:18'),(10,18,'Coonoor','Second largest hill station in Nilgiris known for Sim\'s Park and tea estates.','https://images.unsplash.com/photo-1509024644558-2f56ce76c490?auto=format&fit=crop&w=800&q=80&attraction_id=10',19.00,'2026-07-20 01:30:18'),(11,19,'Tiger Hill','Renowned sunrise viewpoint offering panoramic views of Mount Kanchenjunga.','https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=800&q=80&attraction_id=11',11.00,'2026-07-20 01:30:18'),(12,24,'Fatehpur Sikri','UNESCO World Heritage red sandstone fortified city built by Mughal Emperor Akbar.','https://images.unsplash.com/photo-1507699622108-4be3abd695ad?auto=format&fit=crop&w=800&q=80&attraction_id=12',36.00,'2026-07-20 01:30:18'),(13,25,'Sarnath','Sacred Buddhist pilgrimage site where Lord Buddha delivered his first sermon.','https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=80&attraction_id=13',10.00,'2026-07-20 01:30:18'),(14,26,'Wagah Border','Famous international border outpost hosting the ceremonial retreat by BSF & Pak Rangers.','https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=800&q=80&attraction_id=14',28.00,'2026-07-20 01:30:18'),(15,27,'Kumbhalgarh Fort','Massive hill fort with the second longest continuous wall in the world (36 km).','https://images.unsplash.com/photo-1552832230-c0197dd311b5?auto=format&fit=crop&w=800&q=80&attraction_id=15',84.00,'2026-07-20 01:30:18'),(16,32,'Haridwar','Holy city on the Ganges famous for Har Ki Pauri and evening Ganga Aarti.','https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=800&q=80&attraction_id=16',29.00,'2026-07-20 01:30:18'),(17,33,'Pangong Tso Lake','Breathtaking high-altitude brackish lake famous for changing colors from blue to green.','https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=800&q=80&attraction_id=17',140.00,'2026-07-20 01:30:18'),(18,33,'Nubra Valley','High altitude cold desert known for double-humped Bactrian camels and Diskit Monastery.','https://images.unsplash.com/photo-1503614472-8c93d56e92ce?auto=format&fit=crop&w=800&q=80&attraction_id=18',160.00,'2026-07-20 01:30:18'),(19,1,'Palace of Versailles','Opulent royal chateau featuring Hall of Mirrors and magnificent French gardens.','https://images.unsplash.com/photo-1597074866923-dc0589150358?auto=format&fit=crop&w=800&q=80&attraction_id=19',20.00,'2026-07-20 01:30:18'),(20,3,'Nusa Penida Island','Stunning island off Bali featuring Kelingking T-Rex Beach and Angel\'s Billabong.','https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=800&q=80&attraction_id=20',35.00,'2026-07-20 01:30:18'),(21,7,'Mount Fuji','Japan\'s iconic snow-capped active volcano and highest peak.','https://images.unsplash.com/photo-1546853020-ca4909aef454?auto=format&fit=crop&w=800&q=80&attraction_id=21',100.00,'2026-07-20 01:30:18'),(22,16,'Kufri Snow Point','Scenic hill station 16 km from Shimla known for ski slopes, yak rides, and panoramic Himalayan views.','https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=800&q=80&attraction_id=22',15.50,'2026-07-21 17:19:23'),(23,16,'Jakhoo Hill & Temple','Highest peak in Shimla dedicated to Lord Hanuman, featuring a massive 108-foot idol and valley panoramas.','https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80&attraction_id=23',3.20,'2026-07-21 17:19:23'),(24,21,'Papanasam Beach & Mineral Springs','Holy cliffside beach believed to cleanse sins, featuring natural mineral water springs flowing from red rocks.','https://images.unsplash.com/photo-1564507592333-c60657eea523?auto=format&fit=crop&w=800&q=80&attraction_id=24',1.20,'2026-07-21 17:19:23'),(25,21,'Kappil Lake & Backwaters','Tranquil confluence of backwater estuary and the Arabian Sea with coconut groves and boating.','https://images.unsplash.com/photo-1609949907687-34c82c23f2f0?auto=format&fit=crop&w=800&q=80&attraction_id=25',7.00,'2026-07-21 17:19:23'),(26,38,'Arashiyama Bamboo Grove','Iconic soaring bamboo forest trail that creates a whispering natural atmosphere.','https://images.unsplash.com/photo-1615836245337-f5b9b2303f10?auto=format&fit=crop&w=800&q=80&attraction_id=26',8.50,'2026-07-21 17:19:23'),(27,38,'Fushimi Inari Shrine','Famous Shinto shrine with thousands of vibrant vermilion torii gates mountain path.','https://images.unsplash.com/photo-1600100395164-88484a0d9b4b?auto=format&fit=crop&w=800&q=80&attraction_id=27',4.20,'2026-07-21 17:19:23'),(28,39,'Burj Khalifa Observation Deck','World’s highest outdoor observation deck on the 148th floor offering 360-degree views of Dubai skyline.','https://images.unsplash.com/photo-1581793745862-99fde7fa73d2?auto=format&fit=crop&w=800&q=80&attraction_id=28',0.50,'2026-07-21 17:19:23'),(29,39,'Dubai Miracle Garden','The world’s largest natural flower garden featuring 150 million blooming flowers in full display.','https://images.unsplash.com/photo-1570168007204-dfb528c6958f?auto=format&fit=crop&w=800&q=80&attraction_id=29',14.00,'2026-07-21 17:19:23'),(30,41,'Abbey Falls','Spectacular waterfall cascading down amid spice and coffee plantations.','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=800&q=80&attraction_id=30',6.50,'2026-07-21 17:19:23'),(31,41,'Dubare Elephant Camp','Interactive eco-tourism site on the banks of the Cauvery River where visitors can bathe and feed elephants.','https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=800&q=80&attraction_id=31',28.00,'2026-07-21 17:19:23'),(35,1,'Eif