INSERT INTO `offers` VALUES (1,'Welcome New Traveler','Get flat Rs. 1,500 off on your first booking across any package or hotel stay!','flat',1500.00,'2026-01-01','2026-12-31','all','WELCOME1500','2026-07-20 00:30:58'),(2,'Summer Vacation Sale','Enjoy 15% instant discount on all hill station and beach packages.','percent',15.00,'2026-03-01','2026-08-31','package','SUMMER15','2026-07-20 00:30:58'),(3,'Luxury Hotel Discount','Save flat Rs. 3,000 on luxury 4-star and 5-star hotel bookings.','flat',3000.00,'2026-01-01','2026-12-31','hotel','LUXURY3000','2026-07-20 00:30:58'),(4,'Local Guide Booking Offer','Get 20% off certified local guide bookings when paired with any trip.','percent',20.00,'2026-01-01','2026-12-31','guide','GUIDE20','2026-07-20 00:30:58'),(5,'Winter special discount','for winter season','percent',10.00,'2026-07-22','2026-08-21','hotel','WINTER2026','2026-07-22 04:30:29');
