INSERT INTO `packages` VALUES (1,'Himalayan Snow Adventure & Solang Trek','Experience the best of Manali with snow activities at Solang Valley, hot water springs at Vashisht, and guided trekking in Parvati Valley.',5,14999.00,2,'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=800&q=80','3-Star Hotel Stay, Breakfast & Dinner, Airport/Station Transfer, Solang Valley Pass, Private Cab for Sightseeing','2026-07-20 00:30:58'),(2,'Romantic Bali Beach & Culture Escape','6 Days of paradise in Ubud and Seminyak. Includes private pool villa, floating breakfast, Nusa Penida island boat tour, and Uluwatu sunset dance.',6,45999.00,3,'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=80','5-Star Resort Villa, Breakfast, Fast Boat to Nusa Penida, Spa Massage, English Speaking Guide','2026-07-20 00:30:58'),(3,'Parisian Lights & Louvre Museum Experience','Explore Paris in style! Includes Skip-the-line Eiffel Tower tickets, Seine River Dinner Cruise, and guided walking tour through Montmartre.',4,89999.00,1,'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=800&q=80','Luxury Boutique Hotel, Daily Breakfast, Eiffel Tower Priority Access, Seine Cruise Ticket, Museum Pass','2026-07-20 00:30:58'),(4,'Goa Sun, Sand & Water Sports Package','4 Days of thrilling water sports at Baga Beach, sunset catamaran cruise, heritage tour of Old Goa churches, and casino night experience.',4,11999.00,20,'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=800&q=80','Beachfront Resort, Breakfast, Jet Ski & Parasailing Combo, South Goa Tour, Scooter Rental Included','2026-07-20 00:30:58'),(5,'Royal Rajasthan Jaipur & Udaipur Tour','Discover royal fortresses, lake palaces, and vibrant bazaars across Jaipur and Udaipur with luxury palace hotel stays.',6,28999.00,23,'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80','Heritage Hotel Stays, Daily Buffet Breakfast, Private Chauffeur, Amber Fort Elephant Ride, Lake Pichola Boat Ride','2026-07-20 00:30:58'),(7,'Leh Ladakh High Pass & Pangong Expedition','An epic mountain road trip across Khardung La Pass, Nubra Valley sand dunes, camel rides, and Pangong Lake camping.',7,34999.00,33,'https://images.unsplash.com/photo-1581793745862-99fde7fa73d2?auto=format&fit=crop&w=800&q=80','3-Star Hotel & Luxury Tents, Inner Line Permits, Oxygen Cylinder Support, Breakfast & Dinner, 4x4 SUV Transfer','2026-07-20 00:30:58');
/*!40000 ALTER TABLE `packages` ENABLE KEYS */;
