INSERT INTO `reviews` VALUES (1,24,1,5,'Absolutely breathtaking! The Eiffel Tower light show at night is something I will never forget. Truly the city of love and lights.','2026-07-17 18:15:39'),(2,10,3,4,'Very relaxing trip. Beautiful beaches and extremely friendly locals. Traffic in Ubud can get a bit hectic, but the rest of the island is paradise.','2026-07-17 18:15:39'),(3,21,2,5,'Manali is stunningly beautiful! The mountains, the snow at Rohtang Pass, and the peaceful environment of Old Manali made it an unforgettable vacation.','2026-07-17 18:15:39'),(4,33,16,5,'Walking along Mall Road and sipping hot tea at The Ridge while watching snowfall was magical! Truly a timeless hill station.','2026-07-21 17:19:23'),(5,15,21,5,'The cliffside view overlooking the Arabian Sea is unlike anything else in India. Stunning sunsets and amazing seafood shacks!','2026-07-21 17:19:23'),(6,13,38,5,'Visiting the bamboo grove at sunrise and seeing the golden pavilion left me speechless. Kyoto’s culture is preserved so beautifully.','2026-07-21 17:19:23'),(7,27,39,5,'The desert safari dune bashing and the light show at Burj Khalifa were out of this world! Excellent organization.','2026-07-21 17:19:23'),(8,7,20,5,'Loved the water sports at Baga and the serene vibe at Palolem Beach. Sunset boat cruise is highly recommended!','2026-07-21 17:19:23'),(9,20,23,5,'Amber Palace mirror work (Sheesh Mahal) is pure artistry. The city is full of royal history and great food!','2026-07-21 17:19:23'),(10,17,15,5,'Moraine Lake’s turquoise blue water looks even better in real life than in photos. Best mountain scenery in Canada!','2026-07-21 17:19:23'),(11,21,1,5,'The Seine River dinner cruise and Montmartre art tour were highlights of our trip. Truly romantic and picturesque.','2026-07-21 17:19:23'),(12,12,2,4,'Manali - A absolute hidden gem. Well organized, clean, and full of rich cultural heritage.','2026-07-21 17:33:44'),(13,11,3,5,'Bali - An unforgettable experience! The scenery was breathtaki